INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (365, 1, 17, '敬民篇', NULL, 0, '民惟邦本', '天地之大，黎元为先。', 'http://lcfile.xichuangzhu.com/6a26e673aa263c97a38a.png', '', 9, '用典', 17, '', '', '', '部编版', NULL, '敬民篇', NULL, '民惟邦本', '天地之大，黎元爲先。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (366, 2, 15, '治理篇', NULL, 0, '天下兼相爱则治', '大道之行，天下为公。', 'http://lcfile.xichuangzhu.com/b785a67e7011412ff5c2.png', '', 9, '用典', 31, '', '', '', '部编版', NULL, '治理篇', NULL, '天下兼相愛則治', '大道之行，天下爲公。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (367, 3, 17, '修身篇', NULL, 0, '吾日三省吾身', '人而无信，不知其可也。', 'http://lcfile.xichuangzhu.com/4bb2a85775583975dc82.png', '', 9, '用典', 11, '', '', '', '部编版', NULL, '修身篇', NULL, '吾日三省吾身', '人而無信，不知其可也。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (368, 10, 24, '笃行篇', NULL, 0, '一勤天下无难事', '图难于其易，为大于其细。天下难事，必作于易；天下大事，必作于细。', 'http://lcfile.xichuangzhu.com/b4a4bc6d993027eec0af.png', '', 9, '用典', 34, '', '', '', '部编版', NULL, '篤行篇', NULL, '一勤天下無難事', '圖難於其易，爲大於其細。天下難事，必作於易；天下大事，必作於細。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (369, 11, 28, '劝学篇', NULL, 0, '腹有诗书气自华', '吾生也有涯，而知也无涯。', 'http://lcfile.xichuangzhu.com/f4ae6073d5255743087f.png', '', 9, '用典', 33, '', '', '', '部编版', NULL, '勸學篇', NULL, '腹有詩書氣自華', '吾生也有涯，而知也無涯。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (370, 12, 30, '天下篇', NULL, 0, '计利当计天下利', '立天地之正位，行天下之大道。', 'http://lcfile.xichuangzhu.com/e9dc90f66f11872a8b21.png', '', 9, '用典', 23, '', '', '', '部编版', NULL, '天下篇', NULL, '計利當計天下利', '立天地之正位，行天下之大道。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (371, 13, 23, '廉政篇', NULL, 0, '成由勤俭破由奢', '一丝一粒，我之名节；一厘一毫，民之脂膏。', 'http://lcfile.xichuangzhu.com/e7bc974012ecc6228643.png', '', 9, '用典', 13, '', '', '', '部编版', NULL, '廉政篇', NULL, '成由勤儉破由奢', '一絲一粒，我之名節；一釐一毫，民之脂膏。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (372, 4, 5, '法治篇', NULL, 0, '奉法者强则国强', '立善法于天下，则天下治；立善法于一国，则一国治。', 'http://lcfile.xichuangzhu.com/a9414502bb4c81a0c047.png', '', 9, '用典', 3, '', '', '', '部编版', NULL, '法治篇', NULL, '奉法者強則國強', '立善法於天下，則天下治；立善法於一國，則一國治。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (373, 5, 13, '辩证篇', NULL, 0, '聪者听于无声', '变化者，乃天地之自然。', 'http://lcfile.xichuangzhu.com/ff41885bbd5ff269010a.png', '', 9, '用典', 11, '', '', '', '部编版', NULL, '辯證篇', NULL, '聰者聽於無聲', '變化者，乃天地之自然。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (374, 6, 8, '历史篇', NULL, 0, '古事所以知今', '疑今者，察之古；不知来者，视之往。', 'http://lcfile.xichuangzhu.com/f1143931bcf30f804940.png', '', 9, '用典', 11, '', '', '', '部编版', NULL, '歷史篇', NULL, '古事所以知今', '疑今者，察之古；不知來者，視之往。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (375, 7, 16, '文学篇', NULL, 0, '慈母手中线', '感人心者，莫先乎情。', 'http://lcfile.xichuangzhu.com/627bee83df95fdc82eed.png', '', 9, '用典', 18, '', '', '', '部编版', NULL, '文學篇', NULL, '慈母手中線', '感人心者，莫先乎情。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (376, 14, 11, '立德篇', NULL, 0, '修其心治其身', '修其心治其身，而后可以为政于天下。', 'http://lcfile.xichuangzhu.com/3fc3155ab61963dbea57.png', '', 9, '用典', 11, '', '', '', '部编版', NULL, '立德篇', NULL, '修其心治其身', '修其心治其身，而後可以爲政於天下。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (377, 8, 7, '任贤篇', NULL, 0, '不拘一格降人才', '盖有非常之功，必待非常之人。', 'http://lcfile.xichuangzhu.com/303508c403c1bd5c948a.png', '', 9, '用典', 14, '', '', '', '部编版', NULL, '任賢篇', NULL, '不拘一格降人才', '蓋有非常之功，必待非常之人。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (378, 9, 8, '信念篇', NULL, 0, '君子以自强不息', '天行健，君子以自强不息。', 'http://lcfile.xichuangzhu.com/8e9f2fccde0b24a92962.png', '', 9, '用典', 13, '', '', '', '部编版', NULL, '信念篇', NULL, '君子以自強不息', '天行健，君子以自強不息。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (379, 48, 8, '晏子春秋', NULL, 0, '节俭观念礼的重视', '记叙春秋政治家晏婴言行的书', 'http://lcfile.xichuangzhu.com/1ea7ba3e9030c78a7d5d.jpg', '', 1, '选集', 4, '', '', '', '部编版', NULL, '晏子春秋', NULL, '節儉觀念禮的重視', '記敘春秋政治家晏嬰言行的書', '選集');
