INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (382, 16, 15, '为政篇', NULL, 0, '为政以德', '其身正，不令而行；其身不正，虽令不从。', 'http://lcfile.xichuangzhu.com/3b109dbe5e0098b27a6a.png', '', 9, '用典', 15, '', '', '', '部编版', NULL, '爲政篇', NULL, '爲政以德', '其身正，不令而行；其身不正，雖令不從。', '用典');
INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (383, 15, 20, '竹', NULL, 0, '竹影和诗瘦', '竹影和诗瘦，梅花入梦香。 ', 'http://cdn.xcz.im/img/wenku/xiejing/zhu3.png', '', 3, '写景', 1, '', '', '', '部编版', NULL, '竹', NULL, '竹影和詩瘦', '竹影和詩瘦，梅花入夢香。 ', '寫景');
