INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (409, 65, 25, '月令七十二候集解', NULL, 0, '二十四节气知识', '旧本题“元吴澄撰”。其书以七十二候分属于二十四气，各训释其所以然。考《礼记·月令》，本无七十二候之说。疑好事者为之，托名于澄也。（四库全书总目·经部·礼类存目）', 'http://www.kfzimg.com/sw/kfzimg/323/3ee23b9ee49d91ea_b.jpg', '', 1, '选集', 0, '', '', '', '部编版', NULL, '月令七十二候集解', NULL, '二十四節氣知識', '舊本題“元吳澄撰”。其書以七十二候分屬於二十四氣，各訓釋其所以然。考《禮記·月令》，本無七十二候之說。疑好事者爲之，託名於澄也。（四庫全書總目·經部·禮類存目）', '選集');
