INSERT INTO "collections" ("id", "show_order", "works_count", "name", "abbr", "online_data", "short_desc", "desc", "cover", "link", "kind_id", "kind", "quotes_count", "date", "start_date", "end_date", "press", "book_remote_id", "name_tr", "abbr_tr", "short_desc_tr", "desc_tr", "kind_tr") VALUES (419, 52, 123, '陶庵梦忆', NULL, 1, '张岱散文集', '《陶庵梦忆》，明代散文集。为明朝散文家张岱所著。该书共八卷，成书于甲申明亡（1644年）之后，直至乾隆四十年（1775年）才初版行世。其中所记大多是作者亲身经历过的杂事，将种种世相展现在人们面前。', 'http://cdn.xcz.im/img/wenku/xuanji/tamy.jpg', '', 1, '选集', 0, '', '', '', '部编版', NULL, '陶庵夢憶', NULL, '張岱散文集', '《陶庵夢憶》，明代散文集。爲明朝散文家張岱所著。該書共八卷，成書於甲申明亡（1644年）之後，直至乾隆四十年（1775年）才初版行世。其中所記大多是作者親身經歷過的雜事，將種種世相展現在人們面前。', '選集');
